  public static Dictionary<string,object> Latest(){IntPtr db=IntPtr.Zero,statement=IntPtr.Zero;try{string path=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"NetEase","CloudMusic","Library","webdb.dat");if(!File.Exists(path)||sqlite3_open_v2(Utf8(path),out db,1,IntPtr.Zero)!=0)return null;sqlite3_busy_timeout(db,50);if(sqlite3_prepare_v2(db,Utf8("SELECT jsonStr FROM historyTracks ORDER BY playtime DESC LIMIT 1"),-1,out statement,IntPtr.Zero)!=0||sqlite3_step(statement)!=100)return null;return HookJournal.Json().DeserializeObject(Column(statement,0)) as Dictionary<string,object>;}catch{return null;}finally{if(statement!=IntPtr.Zero)sqlite3_finalize(statement);if(db!=IntPtr.Zero)sqlite3_close(db);}}
  static string Normalize(string value){return (value??"").Trim().Normalize(NormalizationForm.FormC);}
  public static bool Supplement(MusicState state,Dictionary<string,object> record,DateTime processStarted,DateTime now){if(record==null||Normalize(MusicBridge.Str(record,"name"))!=Normalize(state.Title))return false;var artists=MusicBridge.Get(record,"artists") as object[];if(artists==null)return false;string names=string.Join(" / ",artists.Select(a=>MusicBridge.Str(a,"name")));bool all=Normalize(names)==Normalize(state.Artist);string album=Normalize(MusicBridge.Str(MusicBridge.Get(record,"album"),"name"));bool lead=artists.Length>0&&Normalize(MusicBridge.Str(artists[0],"name"))==Normalize(state.Artist);if(!all&&!lead)return false;if(state.Album.Length>0&&album!=Normalize(state.Album))return false;double played,duration;if(!double.TryParse(MusicBridge.Str(record,"playtime"),out played)||!double.TryParse(MusicBridge.Str(record,"duration"),out duration)||!MusicReactions.Finite(played)||!MusicReactions.Finite(duration)||played<0||played>253402300799000||duration<=0||duration>86400000)return false;DateTime at=new DateTime(1970,1,1,0,0,0,DateTimeKind.Utc).AddMilliseconds(played);string id=MusicBridge.Str(record,"id");if(at<processStarted.AddSeconds(-5)||at>now.AddMinutes(5)||!MusicReactions.SongId(id))return false;
   state.Id=id;state.Duration=duration/1000;state.HasDuration=true;state.MetadataSource=all?"本地最新播放记录（歌名、歌手一致）":"本地最新播放记录（歌名、主歌手一致；系统未提供完整歌手）";state.Cover=MusicBridge.Str(MusicBridge.Get(record,"album"),"picUrl");return true;
  }
 }
