  public static async Task<object> Await(object operation,Type resultType){var method=typeof(System.WindowsRuntimeSystemExtensions).GetMethods().First(m=>m.Name=="AsTask"&&m.IsGenericMethod&&m.GetParameters().Length==1&&m.GetParameters()[0].ParameterType.Name.StartsWith("IAsyncOperation`1",StringComparison.Ordinal));var task=(Task)method.MakeGenericMethod(resultType).Invoke(null,new[]{operation});if(await Task.WhenAny(task,Task.Delay(2500)).ConfigureAwait(false)!=task)throw new TimeoutException("系统媒体接口超时");await task.ConfigureAwait(false);return task.GetType().GetProperty("Result").GetValue(task,null);}
  public async Task<MusicState> Read(){var state=new MusicState{ConnectionSource="system",HasPosition=false,HasDuration=false,Label="系统媒体 · 等待普通启动的网易云音乐"};try{
   if(manager==null){var t=TypeOf("Windows.Media.Control.GlobalSystemMediaTransportControlsSessionManager");manager=await Await(t.GetMethod("RequestAsync").Invoke(null,null),t).ConfigureAwait(false);}
   session=((IEnumerable)Call(manager,"GetSessions")).Cast<object>().FirstOrDefault(s=>string.Equals(Convert.ToString(Get(s,"SourceAppUserModelId")),"cloudmusic.exe",StringComparison.OrdinalIgnoreCase));if(session==null)return state;
   var props=await Await(Call(session,"TryGetMediaPropertiesAsync"),TypeOf("Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties")).ConfigureAwait(false);var play=Call(session,"GetPlaybackInfo");var controls=Get(play,"Controls");var timeline=Call(session,"GetTimelineProperties");state.Title=Convert.ToString(Get(props,"Title"));state.Artist=Convert.ToString(Get(props,"Artist"));state.Album=Convert.ToString(Get(props,"AlbumTitle"));state.MetadataSource="系统媒体（无歌曲 ID）";state.Playing=Convert.ToString(Get(play,"PlaybackStatus"))=="Playing";state.CanToggle=Convert.ToBoolean(Get(controls,state.Playing?"IsPauseEnabled":"IsPlayEnabled"));state.CanPrevious=Convert.ToBoolean(Get(controls,"IsPreviousEnabled"));state.CanNext=Convert.ToBoolean(Get(controls,"IsNextEnabled"));state.Connected=!string.IsNullOrWhiteSpace(state.Title);state.At=DateTime.UtcNow;
   TimeSpan end=(TimeSpan)Get(timeline,"EndTime"),start=(TimeSpan)Get(timeline,"StartTime"),position=(TimeSpan)Get(timeline,"Position");DateTimeOffset updated=(DateTimeOffset)Get(timeline,"LastUpdatedTime");if(end>start&&updated.Year>1970&&position>=start&&position<=end){state.HasPosition=state.HasDuration=true;state.Duration=(end-start).TotalSeconds;state.Position=Math.Min(state.Duration,(position-start).TotalSeconds+(state.Playing?Math.Max(0,(state.At-updated.UtcDateTime).TotalSeconds):0));}
   DateTime began=DateTime.UtcNow;var processes=Process.GetProcessesByName("cloudmusic");try{if(processes.Length>0)began=processes.Min(p=>p.StartTime.ToUniversalTime());}finally{foreach(var p in processes)p.Dispose();}
   if(DateTime.UtcNow-cacheAt>TimeSpan.FromSeconds(3)||state.Title!=title||state.Artist!=artist){latest=ReadOnlyMusicCache.Latest();cacheAt=DateTime.UtcNow;}ReadOnlyMusicCache.Supplement(state,latest,began,DateTime.UtcNow);
   string identity=state.Title+"\n"+state.Artist;title=state.Title;artist=state.Artist;if(coverKey!=identity||(cover==null&&DateTime.UtcNow-coverAt>TimeSpan.FromSeconds(5))){coverKey=identity;coverAt=DateTime.UtcNow;cover=null;try{var thumbnail=Get(props,"Thumbnail");if(thumbnail!=null){var stream=await Await(Call(thumbnail,"OpenReadAsync"),TypeOf("Windows.Storage.Streams.IRandomAccessStreamWithContentType","Windows.Storage.Streams")).ConfigureAwait(false);try{var random=TypeOf("Windows.Storage.Streams.IRandomAccessStream","Windows.Storage.Streams");ulong size=(ulong)random.GetProperty("Size").GetValue(stream,null);if(size>0&&size<=1048576){object input=random.GetMethod("GetInputStreamAt").Invoke(stream,new object[]{(ulong)0});var converter=typeof(System.IO.WindowsRuntimeStreamExtensions).GetMethods().First(m=>m.Name=="AsStreamForRead"&&m.GetParameters().Length==1);using(var readable=(Stream)converter.Invoke(null,new[]{input}))using(var memory=new MemoryStream()){await readable.CopyToAsync(memory).ConfigureAwait(false);memory.Position=0;var image=new BitmapImage();image.BeginInit();image.CacheOption=BitmapCacheOption.OnLoad;image.DecodePixelWidth=128;image.StreamSource=memory;image.EndInit();image.Freeze();cover=image;}}}finally{if(Marshal.IsComObject(stream))Marshal.ReleaseComObject(stream);}}}catch{}}
   state.NativeCover=cover;state.Label="系统媒体已连接 · "+(state.Playing?"正在播放":"已暂停")+(state.Id.Length==0?" · 歌曲 ID 待确认":" · 本地 ID 已匹配")+(!state.HasPosition?" · 当前客户端未提供进度":"");return state;
  }catch(Exception e){LastError=e.ToString();state.Connected=false;state.Label="系统媒体暂不可用 · 自动重试";return state;}}
  public async Task<bool> Command(string action,MusicState expected){try{if(session==null||DateTime.UtcNow-expected.At>TimeSpan.FromSeconds(5))return false;var props=await Await(Call(session,"TryGetMediaPropertiesAsync"),TypeOf("Windows.Media.Control.GlobalSystemMediaTransportControlsSessionMediaProperties")).ConfigureAwait(false);if(Convert.ToString(Get(props,"Title"))!=expected.Title||Convert.ToString(Get(props,"Artist"))!=expected.Artist)return false;string method=action=="toggle"?"TryTogglePlayPauseAsync":action=="previous"?"TrySkipPreviousAsync":action=="next"?"TrySkipNextAsync":null;return method!=null&&(bool)await Await(Call(session,method),typeof(bool)).ConfigureAwait(false);}catch{return false;}}
